import os
import time
from typing import Dict, Any, Optional

import requests


class SupabaseAuthTokenRefresher:
    def __init__(
        self,
        supabase_url: Optional[str] = None,
        supabase_anon_key: Optional[str] = None,
        timeout: int = 15,
    ) -> None:
        self.supabase_url = (supabase_url or os.environ["SUPABASE_URL"]).rstrip("/")
        self.supabase_anon_key = supabase_anon_key or os.environ["SUPABASE_ANON_KEY"]
        self.timeout = timeout
        self.refresh_endpoint = f"{self.supabase_url}/auth/v1/token?grant_type=refresh_token"

    def refresh_session(self, refresh_token: str) -> Dict[str, Any]:
        headers = {
            "apikey": self.supabase_anon_key,
            "Authorization": f"Bearer {self.supabase_anon_key}",
            "Content-Type": "application/json",
        }
        payload = {"refresh_token": refresh_token}

        response = requests.post(
            self.refresh_endpoint,
            headers=headers,
            json=payload,
            timeout=self.timeout,
        )

        if response.status_code != 200:
            try:
                error_body = response.json()
            except ValueError:
                error_body = {"error": response.text}
            raise RuntimeError(
                f"Supabase token refresh failed ({response.status_code}): {error_body}"
            )

        data = response.json()
        return {
            "access_token": data["access_token"],
            "refresh_token": data.get("refresh_token", refresh_token),
            "token_type": data.get("token_type", "bearer"),
            "expires_in": data.get("expires_in"),
            "expires_at": (
                int(time.time()) + int(data["expires_in"])
                if data.get("expires_in") is not None
                else data.get("expires_at")
            ),
            "user": data.get("user"),
            "raw": data,
        }
